import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Lote } from '../../lotes/entities/lote.entity';
import { Inspector } from '../../inspectores/entities/inspector.entity';

@Injectable()
export class AsignarInspectorRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Lote) private readonly lotes: Repository<Lote>,
    @InjectRepository(Inspector) private readonly inspectores: Repository<Inspector>
  ) {}

  buscarLoteRepository(loteId: number) {
    return this.lotes.findOneBy({ id: loteId });
  }

  buscarInspectorRepository(inspectorId: number) {
    return this.inspectores.findOneBy({ id: inspectorId });
  }

  async asignarInspectorRepository(loteId: number, inspectorId: number, rol: string) {
    const asignacion = { loteId, inspectorId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarInspectorRepository } from './repository';

@Injectable()
export class AsignarInspectorService {
  constructor(private readonly repository: AsignarInspectorRepository) {}

  async asignarInspectorService(loteId: number, inspectorId: number, rol: string) {
    const lote = await this.repository.buscarLoteRepository(loteId);
    const inspector = await this.repository.buscarInspectorRepository(inspectorId);
    if (!lote || !inspector) {
      throw new NotFoundException('No existe el lote o el inspector');
    }

    try {
      return await this.repository.asignarInspectorRepository(loteId, inspectorId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El inspector ya está asignado a ese lote');
      }
      throw error;
    }
  }
}

import { Body, Controller, Param, Post } from '@nestjs/common';
import { AsignarInspectorService } from './service';

@Controller('lotes/:loteId/asignaciones')
export class AsignarInspectorController {
  constructor(private readonly service: AsignarInspectorService) {}

  @Post()
  asignar(@Param('loteId') loteId: string, @Body() datos: { inspectorId: number; rol: string }) {
    return this.service.asignarInspectorService(Number(loteId), datos.inspectorId, datos.rol);
  }
}
